import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, copyFileSync, writeFileSync, mkdirSync, readFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { strFromU8, unzipSync } from 'fflate';
import { appendBlocks, inspectBodyFlow } from '../lib/engine.js';
import * as core from '@rhwp/core';
import { anchorInfo, bodyLocation, outlineCounters, readHeaderXml, styleMismatches } from '../lib/hwpx-read.js';
import { getForm } from '../lib/forms.js';

const PNG_4x4 = Buffer.from(
  'iVBORw0KGgoAAAANSUhEUgAAAAQAAAAECAYAAACp8Z5+AAAAEklEQVR4nGP4z8DwHxkzkC4AADxAH+HggXe0AAAAAElFTkSuQmCC',
  'base64');
const SKEL = new URL('../forms/kigam-annual/skeleton.hwpx', import.meta.url).pathname;

function workspace() {
  const d = mkdtempSync(join(tmpdir(), 'hwpx-layout-'));
  mkdirSync(join(d, 'fig'));
  writeFileSync(join(d, 'fig/a.png'), PNG_4x4);
  copyFileSync(SKEL, join(d, 'in.hwpx'));
  return d;
}

async function build(blocks) {
  const d = workspace();
  const out = join(d, 'out.hwpx');
  await appendBlocks(join(d, 'in.hwpx'), out, { session: { date: '2026-09-29', project: 't' }, blocks }, d);
  const bytes = readFileSync(out);
  const entries = unzipSync(bytes);
  return {
    bytes,
    xml: strFromU8(entries['Contents/section0.xml']),
    header: strFromU8(entries['Contents/header.xml']),
  };
}

const unescape = (s) => s.replaceAll('&lt;', '<').replaceAll('&gt;', '>').replaceAll('&amp;', '&');

// Innermost paragraphs with their text and paraPr id.
function paragraphs(xml) {
  return [...xml.matchAll(/<hp:p\b[^>]*paraPrIDRef="(\d+)"[^>]*>((?:(?!<hp:p\b)[\s\S])*?)<\/hp:p>/g)]
    .map((m) => ({ paraPr: m[1], text: unescape([...m[2].matchAll(/<hp:t>([^<]*)<\/hp:t>/g)].map((t) => t[1]).join('')) }));
}

function paraPr(header, id) {
  return header.match(new RegExp(`<hh:paraPr id="${id}"[\\s\\S]*?</hh:paraPr>`))[0];
}

const alignOf = (header, id) => /<hh:align horizontal="(\w+)"/.exec(paraPr(header, id))[1];
const prevSpacing = (header, id) => {
  const block = paraPr(header, id);
  const deflt = block.match(/<hp:default>([\s\S]*?)<\/hp:default>/)?.[1] ?? block;
  return Number(/<hc:prev value="(-?\d+)"/.exec(deflt)[1]);
};

// Engine-generated tables sit in the body: after the 3-1 heading, before the summary table.
const bodyStart = (xml) => xml.indexOf('3-1 정성적 연구개발성과');
function nestedTables(xml) {
  const body = xml.slice(bodyStart(xml), anchorInfo(xml).summaryTableIndex);
  return [...body.matchAll(/<hp:tbl\b[^>]*>[\s\S]*?<\/hp:tbl>/g)].map((m) => m[0]);
}

// Top-level paragraphs (not inside a table cell) with their own text.
function topLevelTexts(xml) {
  const out = [];
  const stack = [];
  let depth = 0;
  for (const m of xml.matchAll(/<hp:tbl(?=[\s/>])[^>]*>|<\/hp:tbl>|<hp:p(?=[\s/>])[^>]*>|<\/hp:p>/g)) {
    const t = m[0];
    if (t.startsWith('<hp:tbl')) depth += 1;
    else if (t === '</hp:tbl>') depth -= 1;
    else if (t.startsWith('<hp:p')) stack.push({ start: m.index, depth });
    else {
      const open = stack.pop();
      if (open.depth === 0 && stack.length === 0) {
        const own = xml.slice(open.start, m.index).replace(/<hp:tbl\b[\s\S]*<\/hp:tbl>/g, '');
        out.push(unescape([...own.matchAll(/<hp:t>([^<]*)<\/hp:t>/g)].map((x) => x[1]).join('')));
      }
    }
  }
  return out;
}

test('content tables: padded cells, left-aligned sentence columns, repeated header row', async () => {
  const long = '여러 줄로 줄바꿈되는 긴 설명 문장이 들어가는 칸';
  const { xml, header } = await build([
    { type: 'heading1', text: '표' },
    { type: 'table', caption: '표 제목', headers: ['구분', '설명', '수치'],
      rows: [['가', long, '12.3'], ['나', '짧음', '4']] },
    { type: 'statement', text: '표 뒤 문장임.' },
  ]);
  const [table] = nestedTables(xml);
  assert.match(table, /<hp:tbl\b[^>]*repeatHeader="1"/);
  const margins = [...table.matchAll(/<hp:cellMargin\b[^>]*top="(\d+)"[^>]*bottom="(\d+)"/g)];
  assert.equal(margins.length, 9);
  for (const m of margins) {
    assert.deepEqual([Number(m[1]), Number(m[2])], [280, 280]);
  }
  const cells = paragraphs(table);
  const align = (text) => alignOf(header, cells.find((p) => p.text === text).paraPr);
  assert.equal(align(long), 'LEFT');
  assert.equal(align('짧음'), 'LEFT'); // same column as the long sentence
  assert.equal(align('가'), 'CENTER');
  assert.equal(align('12.3'), 'CENTER');
  assert.equal(align('설명'), 'CENTER'); // header row stays centred

  const after = paragraphs(xml).find((p) => p.text === '◯ 표 뒤 문장임.');
  assert.ok(prevSpacing(header, after.paraPr) > 0, 'paragraph after a table has space before it');
});

test('angle-caption figures carry the caption in an unsplittable figure table', async () => {
  const { xml } = await build([
    { type: 'heading1', text: '그림' },
    { type: 'figure_grid', images: ['fig/a.png', 'fig/a.png'], columns: 2, caption: '두 그림', captionStyle: 'angle' },
    { type: 'statement', text: '그림 뒤 문장임.' },
  ]);
  const [figure] = nestedTables(xml);
  assert.match(figure, /<hp:tbl\b[^>]*pageBreak="NONE"/);
  assert.match(figure, /<hp:tbl\b[^>]*rowCnt="2"/);
  assert.ok(paragraphs(figure).some((p) => p.text === '<두 그림>'), 'caption is inside the figure table');
  const outside = paragraphs(xml.replace(figure, ''));
  assert.ok(!outside.some((p) => p.text === '<두 그림>'), 'no separate caption paragraph');
});

test('numbered figure captions keep the original paragraph form', async () => {
  const { xml } = await build([
    { type: 'bullet1', text: '성과' },
    { type: 'figure_grid', images: ['fig/a.png'], columns: 1, caption: '그림 설명' },
  ]);
  const [figure] = nestedTables(xml);
  assert.doesNotMatch(figure, /그림 1\./);
  assert.ok(paragraphs(xml).some((p) => p.text === '그림 1. 그림 설명'));
});

function orphanDraft(lines) {
  const blocks = [{ type: 'heading1', text: '절' }];
  for (let i = 0; i < lines; i += 1) {
    blocks.push({ type: 'detail', text: `한 줄 문장 ${i}` });
  }
  blocks.push({ type: 'heading2', text: '항 제목' }, { type: 'heading3', text: '목 제목' },
    { type: 'statement', text: '본문 문장' });
  for (let i = 0; i < 8; i += 1) {
    blocks.push({ type: 'detail', text: `뒤 문장 ${i}` });
  }
  blocks.push({ type: 'table', caption: '표 제목', headers: ['a', 'b'], rows: [['1', '2'], ['3', '4']] });
  for (let i = 0; i < 30; i += 1) {
    blocks.push({ type: 'detail', text: `더 ${i}` });
  }
  return blocks;
}

// Filler lengths that put the heading chain at a page bottom in the rhwp layout (2026-09-29).
for (const lines of [28, 29]) {
  test(`keep-with-next headings move to the next page (filler ${lines})`, async () => {
    const { bytes } = await build(orphanDraft(lines));
    const { pages, keep } = await inspectBodyFlow(bytes);
    for (let i = 0; i + 1 < pages.length; i += 1) {
      assert.ok(!(keep[i] && pages[i + 1] > pages[i]),
        `paragraph ${i} keeps with next but ends page ${pages[i] + 1}`);
    }
  });
}

test('the body is ordinary text outside any table, between the 3-1 heading and the summary table', async () => {
  const { xml } = await build([
    { type: 'heading1', text: '가 절' },
    { type: 'statement', text: '본문 문장임.' },
    { type: 'table', caption: '표 제목', headers: ['a'], rows: [['1']] },
  ]);
  const texts = topLevelTexts(xml);
  const heading = texts.findIndex((t) => t.includes('3-1 정성적 연구개발성과'));
  assert.ok(heading >= 0);
  assert.deepEqual(texts.slice(heading + 1).filter(Boolean), ['가. 가 절', '◯ 본문 문장임.', '<표 제목>']);
  // no 1x1 box around the body: the only tables are the goal, content and summary tables
  const shapes = [...xml.matchAll(/<hp:tbl\b[^>]*rowCnt="(\d+)" colCnt="(\d+)"/g)].map((m) => `${m[1]}x${m[2]}`);
  assert.ok(!shapes.includes('1x1'), shapes.join(','));
});

test('a form that still keeps the body in the old 1x1 box is refused', () => {
  const box = '<hp:p><hp:run><hp:tbl numberingType="TABLE" rowCnt="1" colCnt="1"><hp:tr><hp:tc><hp:subList>'
    + '<hp:p><hp:run><hp:tbl numberingType="TABLE" rowCnt="7" colCnt="4"><hp:t>구분</hp:t><hp:t>주요 목록 및 내용</hp:t>'
    + '<hp:t>활용 목적</hp:t></hp:tbl></hp:run></hp:p></hp:subList></hp:tc></hp:tr></hp:tbl></hp:run></hp:p>';
  assert.throws(() => bodyLocation(box, getForm('kigam-annual')), /old 1x1 box/);
});

async function buildDraft(draft) {
  const d = workspace();
  const out = join(d, 'out.hwpx');
  await appendBlocks(join(d, 'in.hwpx'), out, { session: { date: '2026-09-29', project: 't' }, ...draft }, d);
  return { dir: d, out, bytes: readFileSync(out) };
}

test('form fills the goal table rows and the summary table, only while they are empty', async () => {
  const goals = [['목표 가', '내용 가', '100'], ['목표 나', '내용 나', '100'], ['목표 다', '내용 다', '100']];
  const summary = [['구분 가', '목록 가', '출처 가', '목적 가']];
  const { dir, out } = await buildDraft({ blocks: [{ type: 'statement', text: '본문.' }], form: { goals, summary } });
  const xml = strFromU8(unzipSync(readFileSync(out))['Contents/section0.xml']);
  const goalTable = xml.slice(xml.lastIndexOf('<hp:tbl', xml.indexOf('추 진 목 표')));
  assert.match(goalTable, /<hp:tbl\b[^>]*rowCnt="4"/);
  const summaryStart = anchorInfo(xml).summaryTableIndex;
  const filled = xml.slice(xml.lastIndexOf('<hp:tc', xml.indexOf('<hp:t>구분 가</hp:t>')));
  assert.equal([...filled.slice(0, filled.indexOf('</hp:tc>')).matchAll(/<hp:p\b/g)].length, 1, 'no blank guide lines under the text');
  for (const text of goals.flat()) {
    const at = xml.indexOf(`<hp:t>${text}</hp:t>`);
    assert.ok(at > 0 && at < bodyStart(xml), `${text} in the goal table`);
  }
  for (const text of summary.flat()) {
    assert.ok(xml.indexOf(`<hp:t>${text}</hp:t>`) > summaryStart, `${text} in the summary table`);
  }
  // a second append that brings form rows again must not overwrite the filled tables
  await assert.rejects(appendBlocks(out, join(dir, 'again.hwpx'),
    { session: { date: '2026-09-29', project: 't' }, blocks: [{ type: 'statement', text: '추가.' }], form: { goals } }, dir),
  /goal table already has content/);
});

test('goal rows grow to the height of their wrapped text', async () => {
  const long = '두 줄 이상으로 줄이 바뀌도록 달성 내용을 충분히 길게 적은 문장이며 칸의 폭을 넘음';
  const goals = [['목표 가', long, '100'], ['목표 나', long, '100'], ['목표 다', long, '100']];
  const { out } = await buildDraft({ blocks: [{ type: 'statement', text: '본문.' }], form: { goals } });
  const xml = strFromU8(unzipSync(readFileSync(out))['Contents/section0.xml']);
  const start = xml.lastIndexOf('<hp:tbl', xml.indexOf('추 진 목 표'));
  const table = xml.slice(start, xml.indexOf('</hp:tbl>', start));
  const rows = table.split(/<hp:tr\b/).slice(2);
  assert.equal(rows.length, goals.length);
  for (const row of rows) {
    const tc = row.split(/<hp:tc\b/).slice(1).find((c) => c.includes('두 줄 이상'));
    const bottoms = [...tc.matchAll(/vertpos="(\d+)"[^>]*vertsize="(\d+)"/g)].map((m) => Number(m[1]) + Number(m[2]));
    assert.ok(Math.max(...bottoms) > 1560, 'the long cell wraps');
    const [, top, bottom] = tc.match(/<hp:cellMargin\b[^>]*top="(\d+)"[^>]*bottom="(\d+)"/);
    const heights = [...row.matchAll(/<hp:cellSz\b[^>]*height="(\d+)"/g)].map((m) => Number(m[1]));
    assert.ok(heights.every((h) => h === heights[0]), 'one height per row');
    assert.ok(heights[0] >= Math.max(...bottoms) + Number(top) + Number(bottom), `row height ${heights[0]}`);
  }
});

// Top-level text is paginated by the renderer; a long content table splits over pages and a
// figure that does not fit moves to the next page, so nothing is drawn below the body area.
function overflowDraft(lines) {
  const goals = Array.from({ length: 6 }, (_, i) => [`목표 ${i}`, '달성 내용을 두 줄 정도로 길게 적은 문장임', '100']);
  const blocks = [{ type: 'heading1', text: '절' }];
  for (let i = 0; i < lines; i += 1) {
    blocks.push({ type: 'detail', text: `한 줄 문장 ${i}` });
  }
  blocks.push({ type: 'table', caption: '표 제목', headers: ['a', 'b'],
    rows: Array.from({ length: 6 }, (_, i) => [`${i}`, '값']) });
  blocks.push({ type: 'statement', text: '표 뒤 문장.' });
  return { blocks, form: { goals } };
}

test('nothing runs below the body area and no heading or table title ends a page', async () => {
  for (const lines of [14, 16, 18, 24, 26, 28]) {
    const { bytes } = await buildDraft(overflowDraft(lines));
    const { overflow, pages, keep } = await inspectBodyFlow(bytes);
    assert.deepEqual(overflow.flatMap((over, i) => (over ? [i] : [])), [], `filler ${lines}: overflow`);
    for (let i = 0; i + 1 < pages.length; i += 1) {
      assert.ok(!(keep[i] && pages[i + 1] > pages[i]), `filler ${lines}: paragraph ${i} left at a page end`);
    }
  }
});

test('a figure that does not fit the rest of a page moves whole to the next page', async () => {
  const d = workspace();
  // 40 x 30 px: drawn at the full text width it takes about three quarters of a page
  const wide = Buffer.from('iVBORw0KGgoAAAANSUhEUgAAACgAAAAeCAIAAADRv8uKAAAAKUlEQVR4nO3NsQ0AAAgDoJ7ez/UMHUjYSTsnIhaLxWKxWCwWi8Xiv/ECAjZb2IjXz/cAAAAASUVORK5CYII=', 'base64');
  writeFileSync(join(d, 'fig/wide.png'), wide);
  const blocks = [{ type: 'heading1', text: '절' }];
  for (let i = 0; i < 20; i += 1) blocks.push({ type: 'detail', text: `한 줄 문장 ${i}` });
  blocks.push({ type: 'figure_grid', images: ['fig/wide.png'], columns: 1, caption: '넓은 그림', captionStyle: 'angle' });
  const out = join(d, 'out.hwpx');
  const res = await appendBlocks(join(d, 'in.hwpx'), out, { session: { date: '2026-09-29', project: 't' }, blocks }, d);
  assert.deepEqual(res.layout.overflow, []);
  const bytes = readFileSync(out);
  const { pages, lastPages } = await inspectBodyFlow(bytes);
  const figure = pages.length - 2; // the summary table follows the figure
  assert.equal(pages[figure], lastPages[figure], 'the figure is not split');
  const xml = strFromU8(unzipSync(bytes)['Contents/section0.xml']);
  const figureTable = xml.slice(xml.lastIndexOf('<hp:tbl', xml.indexOf('&lt;넓은 그림&gt;')));
  assert.match(figureTable, /^<hp:tbl\b[^>]*>[^]*?<hp:pos\b[^>]*treatAsChar="1"/, 'treated as a character so Hancom moves it whole');
  assert.ok(pages[figure] > pages[figure - 1], 'the figure starts a new page');
});

// Independent of inspectBodyFlow: the page on which the rendered text containing `needle` starts.
async function pageOfText(bytes, needle) {
  await inspectBodyFlow(bytes); // initialises the wasm module shared with the engine
  const doc = new core.HwpDocument(new Uint8Array(bytes));
  for (let page = 0; page < doc.pageCount(); page += 1) {
    const runs = JSON.parse(doc.getPageTextLayout(page)).runs ?? [];
    if (runs.map((r) => r.text).join('').includes(needle)) {
      return page;
    }
  }
  return -1;
}

test('rendered text: moved headings sit on the page of the text they introduce', async () => {
  for (const lines of [28, 29]) {
    const { bytes } = await build(orphanDraft(lines));
    const heading = await pageOfText(bytes, '항 제목');
    assert.ok(heading >= 0, 'heading text found in the render');
    assert.equal(await pageOfText(bytes, '목 제목'), heading, `filler ${lines}`);
    assert.equal(await pageOfText(bytes, '본문 문장'), heading, `filler ${lines}`);
  }
});

test('a table running over two pages splits by rows and adds no page start after it', async () => {
  // rhwp 0.8.6 sometimes starts the next paragraph on a new page after a split table on its own
  // (seen at some row counts, with or without cell margins), and draws a table only slightly taller
  // than the body area unsplit (reported as overflow); 60 rows is a length where neither happens
  const rows = Array.from({ length: 60 }, (_, i) => [`행 ${i}`, '값']);
  const { bytes, xml } = await build([
    { type: 'heading1', text: '긴 표' },
    { type: 'table', caption: '긴 표 제목', headers: ['a', 'b'], rows },
    { type: 'statement', text: '긴 표 뒤 문장.' },
  ]);
  const { pages, lastPages, texts } = await inspectBodyFlow(bytes);
  const table = texts.findIndex((t) => t.includes('긴 표 제목')) + 1;
  assert.ok(lastPages[table] > pages[table], 'the table spans pages');
  const long = xml.slice(xml.lastIndexOf('<hp:tbl', xml.indexOf('<hp:t>행 0</hp:t>')));
  assert.match(long, /^<hp:tbl\b[^>]*pageBreak="CELL"/);
  assert.match(long, /^<hp:tbl\b[^>]*>[^]*?<hp:pos\b[^>]*treatAsChar="0"/, 'a long table stays floating so it can split');
  assert.ok(!/<hp:p\b[^>]*pageBreak="1"/.test(xml.slice(xml.indexOf('긴 표 뒤 문장') - 2000, xml.indexOf('긴 표 뒤 문장'))
    .split('</hp:tbl>').pop()), 'no page break before the sentence');
  assert.equal(await pageOfText(bytes, '긴 표 뒤 문장'), lastPages[table]);
});

async function drawnTexts(bytes) {
  await inspectBodyFlow(bytes); // initialises the wasm module shared with the engine
  const doc = new core.HwpDocument(new Uint8Array(bytes));
  const texts = [];
  for (let page = 0; page < doc.pageCount(); page += 1) {
    texts.push(...(JSON.parse(doc.getPageTextLayout(page)).runs ?? []).map((r) => r.text));
  }
  return texts.join(''); // a cell text can come in several runs ('행 ', '0')
}

// Tables a little taller than a page: rhwp 0.8.6 once started the paragraph after the 70-row table
// on a new page by itself, and drew the 50-row table unsplit past the page bottom while it was
// marked not to split. The engine must not add breaks of its own there, must not lose rows, and
// must report what runs past the page bottom.
for (const [rows, note] of [[70, 'long table'], [50, 'a little taller than the body']]) {
  test(`known rhwp limit (${rows} rows, ${note}): no engine break after the table, rows kept, overflow reported`, async () => {
    const d = workspace();
    const out = join(d, 'out.hwpx');
    const res = await appendBlocks(join(d, 'in.hwpx'), out, { session: { date: '2026-09-29', project: 't' }, blocks: [
      { type: 'heading1', text: '긴 표' },
      { type: 'table', caption: '긴 표 제목', headers: ['a', 'b'], rows: Array.from({ length: rows }, (_, i) => [`행 ${i}`, '값']) },
      { type: 'statement', text: '긴 표 뒤 문장.' }] }, d);
    const bytes = readFileSync(out);
    const xml = strFromU8(unzipSync(bytes)['Contents/section0.xml']);
    const after = paragraphs(xml).find((p) => p.text === '◯ 긴 표 뒤 문장.');
    assert.ok(after, 'the sentence is there');
    assert.ok(!/<hp:p\b[^>]*pageBreak="1"[^>]*>(?:(?!<\/hp:p>)[\s\S])*긴 표 뒤 문장/.test(xml), 'no engine break before the sentence');
    const drawn = await drawnTexts(bytes);
    for (let i = 0; i < rows; i += 1) {
      assert.ok(drawn.includes(`행 ${i}값`), `row ${i} is drawn`);
    }
    // overflow read independently from the raw control layout: the table's box against the page bottom
    const doc = new core.HwpDocument(new Uint8Array(bytes));
    let tableBelow = false;
    for (let page = 0; page < doc.pageCount(); page += 1) {
      const info = JSON.parse(doc.getPageInfo(page));
      for (const c of JSON.parse(doc.getPageControlLayout(page)).controls ?? []) {
        if (c.type === 'table' && (c.stableIndex?.length ?? 0) === 3 && c.y + c.h > info.height - info.marginBottom + 1
          && c.h > 200) {
          tableBelow = true;
        }
      }
    }
    const { texts } = await inspectBodyFlow(bytes);
    const table = texts.findIndex((t) => t.includes('긴 표 제목')) + 1;
    assert.equal(res.layout.overflow.includes(table), tableBelow, 'the table is reported exactly when it runs past the page bottom');
  });
}

test('a table almost a page tall is kept whole on the next page', async () => {
  const blocks = [{ type: 'heading1', text: '절' }];
  for (let i = 0; i < 20; i += 1) blocks.push({ type: 'detail', text: `한 줄 문장 ${i}` });
  blocks.push({ type: 'table', caption: '거의 한 쪽인 표', headers: ['a', 'b'], rows: Array.from({ length: 42 }, (_, i) => [`행 ${i}`, '값']) });
  const d = workspace();
  const out = join(d, 'out.hwpx');
  const res = await appendBlocks(join(d, 'in.hwpx'), out, { session: { date: '2026-09-29', project: 't' }, blocks }, d);
  const bytes = readFileSync(out);
  const { pages, lastPages, texts, tableHeights, bodyHeight } = await inspectBodyFlow(bytes);
  const table = texts.findIndex((t) => t.includes('거의 한 쪽인 표')) + 1;
  assert.ok(tableHeights[table] > bodyHeight * 0.85, `the table is ${(tableHeights[table] / bodyHeight).toFixed(2)} of the body`);
