test('SVG checks refuse DTD entities, foreign content and CSS references but keep the W3C doctype', async () => {
  const { svgInfo } = await import('../lib/svg.js');
  const svg = (body, prolog = '') => Buffer.from(`${prolog}<svg xmlns="http://www.w3.org/2000/svg" width="10" height="10">${body}</svg>`);
  const refused = {
    'entities or an external DTD': [svg('', '<!DOCTYPE svg [<!ENTITY x "y">]>'),
      svg('', '<!DOCTYPE svg SYSTEM "x.dtd">'),
      svg('', '<!DOCTYPE svg PUBLIC "-//W3C//DTD SVG 1.1//EN" "http://example.org/svg11.dtd">')],
    'foreign content': [svg('<foreignObject width="1" height="1"/>'),
      svg('<s:foreignObject xmlns:s="http://www.w3.org/2000/svg"/>')],
    'script or event handler': [svg('<s:script xmlns:s="http://www.w3.org/2000/svg">x()</s:script>'),
      svg('<rect o&#110;load="x()"/>'), svg('<&#115;cript>x()</&#115;cript>')],
    'outside resource': [svg('<rect style="fill:url(https://example.org/p)"/>'), svg('<style>@import "x.css";</style>'),
      svg('<rect style="fill:u\\72l(https://example.org/p)"/>'), svg('<a:image xmlns:a="http://www.w3.org/1999/xlink" a:href="https://example.org/x.png"/>'),
      svg('<image href="data:image/svg+xml;base64,AAAA"/>')],
  };
  for (const [message, buffers] of Object.entries(refused)) {
    for (const b of buffers) {
      assert.throws(() => svgInfo(b), new RegExp(message), b.toString());
    }
  }
  const sized = (attrs) => Buffer.from(`<svg xmlns="http://www.w3.org/2000/svg" ${attrs}/>`);
  for (const attrs of ['width="0.4" height="10"', 'viewBox="0 0 Infinity 10"', 'width="10"', 'width="1e9" height="1"', 'width="10%" height="10%"']) {
    assert.throws(() => svgInfo(sized(attrs)), /SVG/, attrs);
  }
  assert.deepEqual(svgInfo(sized('width="10.5pt" viewBox="0 0 1 1" height="3pt"')), { width: 14, height: 4 });
  const w3c = '<!DOCTYPE svg PUBLIC "-//W3C//DTD SVG 1.1//EN"\n  "http://www.w3.org/Graphics/SVG/1.1/DTD/svg11.dtd">';
  assert.deepEqual(svgInfo(svg('<rect clip-path="url(#c)"/>', w3c)), { width: 10, height: 10 });
});

